import {
  Box,
  Code,
  DocsSection,
  Header,
  HookSignature,
  HookSignatureItem,
  type Section
} from "react-lib-tools";

/** Generated by `compile:types` */
export type ModelTypeMetadata = {
  description: Section[];
  fields: {
    description: Section[];
    name: string;
    optional: boolean;
    type: string;
  }[];
  html?: string | undefined;
  name: string;
};

/**
 * Page documenting one of the types that make up a workspace's model.
 */
export function ModelType({ json }: { json: ModelTypeMetadata }) {
  return (
    <Box direction="column" gap={4}>
      <Header section="Model" title={json.name} />
      <DocsSection sections={json.description} />
      {json.html && <Code html={json.html} />}
      {json.fields.length > 0 && (
        <HookSignature>
          {json.fields.map((field) => (
            <HookSignatureItem
              key={field.name}
              name={field.name}
              optional={field.optional}
              type={field.type}
            >
              <DocsSection sections={field.description} />
            </HookSignatureItem>
          ))}
        </HookSignature>
      )}
    </Box>
  );
}
